SELECT * FROM cus_project_customer_contact_relation
WHERE tenant_id=#{query.tenantId} AND project_id=#{query.projectId} AND customer_contact_id=#{query.sourceContactId}
FOR UPDATE

SELECT r.id,r.version, CASE WHEN r.deleted=b'1' AND r.customer_id=#{query.customerId} AND c.deleted=b'0' AND (r.status=1 OR (c.lifecycle_status='ENABLED' AND s.status=0 AND s.deleted=b'0')) THEN 1 ELSE 0 END AS restorable FROM cus_project_customer_contact_relation r LEFT JOIN cus_customer_master c ON c.id=r.customer_id AND c.tenant_id=r.tenant_id LEFT JOIN cus_customer_contact s ON s.id=r.customer_contact_id AND s.tenant_id=r.tenant_id WHERE r.tenant_id=#{query.tenantId} AND r.project_id=#{query.projectId}
AND r.id IN #{id}
AND 1=0
